fn solve(n: i8) -> i8 {
    // Use a greedy decomposition with denominations 100, 20, 10, 5, and 1.
    let mut remaining = n;
    let mut count = 0;

    // 100-unit notes
    count += remaining / 100;
    remaining %= 100;

    // 20-unit notes
    count += remaining / 20;
    remaining %= 20;

    // 10-unit coins
    count += remaining / 10;
    remaining %= 10;

    // 5-unit coins
    count += remaining / 5;
    remaining %= 5;

    // 1-unit coins
    count += remaining; 

    count
}

